pm.test("Validate user data", function () {
    let user = pm.response.json();

    pm.expect(user).to.be.an("object");
    pm.expect(user.id).to.eql(1);
    pm.expect(user.firstName).to.eql("Emily");
    pm.expect(user.lastName).to.eql("Johnson");
    pm.expect(user.age).to.eql(29);
    pm.expect(user.gender).to.eql("female");
    pm.expect(user.email).to.include("@");
    pm.expect(user.phone).to.match(/^\+/);
    pm.expect(user.birthDate).to.eql("1996-5-30");
    pm.expect(user.bloodGroup).to.eql("O-");
    pm.expect(user.eyeColor).to.eql("Green");
    pm.expect(user.hair.color).to.eql("Brown");
    pm.expect(user.hair.type).to.eql("Curly");
    pm.expect(user.address.country).to.eql("United States");
    pm.expect(user.company.department).to.eql("Engineering");
    pm.expect(user.company.title).to.eql("Sales Manager");
    pm.expect(user.crypto.coin).to.eql("Bitcoin");
    pm.expect(user.crypto.network).to.eql("Ethereum (ERC20)");
    pm.expect(user.role).to.eql("admin");
});

